const short = value => typeof value==='string'?value.slice(0,12):'—';
const date = value => value==null?'':new Date(typeof value==='number'?value*1000:value).toLocaleString();
const titles = {overview:'Workspace overview',discover:'Discover & acquire',sources:'Retained source evidence',mapping:'Mapping review',editions:'Editions & native queries',receive:'Customer receiving',activity:'Activity & recovery'};
const model = {state:null,workspace:null,source:null,sourcePage:null,sourceStack:[],mapping:null,mappingSource:null,planId:null,build:null,nativePages:[],nativeIndex:0,comparison:null,changeStack:[],changePage:null,connection:null,queryChoices:[],queryCollection:null,queryId:null,querySaved:null,discovery:null,received:null,requests:[],recordPage:null,recordStack:[],busy:0};
