async function action(name,fn){if(busyNames.has(name))return;busyNames.add(name);model.busy++;document.body.setAttribute('aria-busy','true');try{return await fn();}catch(error){fail(error);return null;}finally{busyNames.delete(name);model.busy--;document.body.setAttribute('aria-busy',String(model.busy>0));}}
