function jsonText(raw,label,expected){let value;try{value=JSON.parse(raw);}catch{throw new Error(label+' must be complete valid JSON.');}if(expected==='object'&&(!value||Array.isArray(value)||typeof value!=='object'))throw new Error(label+' must be a JSON object.');if(expected==='array'&&!Array.isArray(value))throw new Error(label+' must be a JSON array.');return value;}
function integerValue(id){const raw=$(id).value;if(!/^(0|[1-9][0-9]*)$/.test(raw)||!Number.isSafeInteger(Number(raw)))throw new Error('Review the whole-number value for '+$(id).closest('label').childNodes[0].textContent.trim());return Number(raw);}
