async function api(route,{method='GET',body,file,headers={}}={}){const response=await fetch(route,{method,credentials:'omit',cache:'no-store',redirect:'error',headers:{Authorization:'Bearer '+capability,...(body!==undefined?{'Content-Type':'application/json'}:{}),...headers},body:file!==undefined?file:body!==undefined?JSON.stringify(body):undefined});const raw=await response.text();let value;try{value=JSON.parse(raw);}catch{const error=new Error('The local server returned an unreadable response. Reopen the retained request before retrying.');error.status=response.status;throw error;}if(!response.ok){const error=new Error(value.error||'Local request returned HTTP '+response.status);error.status=response.status;error.payload=value;throw error;}return value;}
