function openDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('stellar-forge-edr',1);request.onupgradeneeded=()=>{for(const name of ['drafts','requests'])if(!request.result.objectStoreNames.contains(name))request.result.createObjectStore(name,{keyPath:'key'});};request.onerror=()=>reject(request.error||new Error('Browser recovery storage is unavailable'));request.onblocked=()=>reject(new Error('Close an older operator tab so browser recovery storage can open.'));request.onsuccess=()=>resolve(request.result);});}
