function key(name){return model.workspace+':'+name;}
async function readDraft(name){const item=await storage('drafts','readonly',s=>s.get(key(name)));return item?.value;}
async function writeDraft(name,value){return storage('drafts','readwrite',s=>s.put({key:key(name),workspace:model.workspace,value,updated:new Date().toISOString()}));}
