async function requests(){const all=await storage('requests','readonly',s=>s.getAll());model.requests=all.filter(r=>r.workspace===model.workspace).sort((a,b)=>b.created.localeCompare(a.created));return model.requests;}
async function saveRequest(record){await storage('requests','readwrite',s=>s.put(record));}
async function prepareRequest(kind,route,body,{file,headers={}}={}){const id='edr-'+crypto.randomUUID();const record={key:key(id),workspace:model.workspace,id,kind,route,body:body===undefined?null:copy(body),headers,created:new Date().toISOString(),status:'prepared',result:null,error:null};if(file){record.file=file;record.fileName=file.name;record.fileBytes=file.size;record.fileSha256=await hashBlob(file);}await saveRequest(record);await requests();renderRequests();return record;}
