function safeFile(record){const {file,...rest}=record;return {...rest,file:file?{name:record.fileName,bytes:record.fileBytes,sha256:record.fileSha256}:undefined};}
async function refreshState(){const value=await api('/api/state');if(model.workspace&&model.workspace!==value.workspace.id)throw new Error('The active process belongs to a different workspace. Reopen its original private link.');model.state=value;model.workspace=value.workspace.id;text($('#workspace-name'),value.workspace.name);renderState();return value;}
