function mappingColumns(){return $$('tr',$('#mapping-columns')).map(row=>{const fields=Object.fromEntries($$('[data-column-field]',row).map(node=>[node.dataset.columnField,node.type==='checkbox'?node.checked:node.value]));return {...row.original,...fields,pointer:fields.source==='cell'?fields.pointer:''};});}
function captureMapping(){return {sourceId:model.mappingSource,base:copy(model.mapping),planId:model.planId,columns:mappingColumns(),fields:Object.fromEntries(['name','coverage','keys','filters','ranges','sorts','defaultLimit','maxLimit','maxRows','maxBytes','maxCellChars'].map(name=>[name,$('#mapping-'+name).value])),allowEmpty:$('#mapping-allowEmpty').checked};}
function readMapping(){if(!model.mapping)throw new Error('Open a retained source mapping first.');const value={...copy(model.mapping),name:$('#mapping-name').value,coveragePolicy:$('#mapping-coverage').value,columns:mappingColumns(),allowEmpty:$('#mapping-allowEmpty').checked};for(const k of ['keys','filters','ranges','sorts'])value[k]=jsonText($('#mapping-'+k).value,k,'array');for(const k of ['defaultLimit','maxLimit','maxRows','maxBytes','maxCellChars'])value[k]=integerValue('#mapping-'+k);return value;}
