function renderMapping(mapping,sourceId,planId=null,draft=null){model.mapping=copy(mapping);model.mappingSource=sourceId;model.planId=planId;$('#mapping-form').hidden=false;$('#mapping-source').value=sourceId;$('#mapping-name').value=mapping.name;$('#mapping-coverage').value=mapping.coveragePolicy;for(const k of ['keys','filters','ranges','sorts'])$('#mapping-'+k).value=pretty(mapping[k]);for(const k of ['defaultLimit','maxLimit','maxRows','maxBytes','maxCellChars'])$('#mapping-'+k).value=mapping[k];$('#mapping-allowEmpty').checked=mapping.allowEmpty;clear($('#mapping-columns'));for(const c of draft?.columns||mapping.columns)columnRow(c);if(draft){for(const[k,v]of Object.entries(draft.fields||{}))if($('#mapping-'+k))$('#mapping-'+k).value=v;$('#mapping-allowEmpty').checked=draft.allowEmpty;}text($('#mapping-id'),planId?'Saved mapping '+planId:'Draft · no saved mapping identity yet');const binding=$('#mapping-binding');clear(binding);for(const[label,value]of [['Source',sourceId],['Provider endpoint',mapping.endpoint],['Collection',mapping.collectionId],['Structural schema',mapping.schemaSha256]]){const p=el('p');p.append(el('b','',label+': '),el('span','hash',value));binding.append(p);}if(model.source?.id===sourceId&&model.source.inventory.schemaSha256!==mapping.schemaSha256)binding.append(el('p','', 'The selected source has a different coverage layout. Choose its reviewed mapping before building.'));try{text($('#mapping-json'),pretty(readMapping()));}catch(error){text($('#mapping-json'),'Draft retained. '+error.message);}text($('#mapping-draft-status'),draft?'Recovered this source’s saved browser draft.':planId?'Loaded a complete immutable mapping.':'Review the original coverage layout projection, then save.');}
async function openMapping(sourceId){if(!sourceId)throw new Error('Choose a retained source first.');if(model.source?.id!==sourceId)await selectSource(sourceId,false);const draft=await readDraft('mapping:'+sourceId);if(draft?.base){renderMapping(draft.base,sourceId,draft.planId,draft);}else{const mapping=await api('/api/sources/'+sourceId+'/mapping',{method:'POST',body:{}});renderMapping(mapping,sourceId);await writeDraft('mapping:'+sourceId,captureMapping());}openView('mapping');}
async function loadMapping(){const id=$('#mapping-select').value,sid=$('#mapping-source').value;if(!id||!sid)throw new Error('Select both the source and its saved mapping.');if(model.source?.id!==sid)await selectSource(sid,false);const mapping=await api('/api/plans/'+id);renderMapping(mapping,sid,id);await writeDraft('mapping:'+sid,captureMapping());}
async function saveMapping(){const body=readMapping(),sourceId=model.mappingSource;await writeDraft('mapping:'+sourceId,captureMapping());const {result}=await mutation('mapping','/api/plans',body);const unchanged=model.mappingSource===sourceId&&(()=>{try{return canonical(readMapping())===canonical(body);}catch{return false;}})();$('#build-source').value=sourceId;$('#build-plan').value=result.id;$('#mapping-select').value=result.id;if(unchanged){model.planId=result.id;text($('#mapping-id'),result.id);text($('#mapping-draft-status'),'Saved mapping '+short(result.id)+'.');await writeDraft('mapping:'+sourceId,captureMapping());}else{text($('#mapping-draft-status'),'Earlier review saved as '+short(result.id)+'; your newer draft is preserved.');}notice('Reviewed mapping saved. Select its source and mapping in Editions to build.','success');return result;}
