function renderBuild(){const b=model.build;text($('#build-title'),b.native?.name||'Retained native edition');text($('#build-id'),b.id);const facts=$('#build-facts');clear(facts);facts.append(metric('Native rows',b.rowCount),metric('Columns',b.columns?.length||0),metric('Edition keys',b.keys?.length||0));const snap=el('p','hash help','Snapshot: '+b.native.snapshot);facts.append(snap);text($('#build-review'),pretty(b));for(const id of ['export-packet','export-dataset','native-query'])$('#'+id).disabled=false;$('#native-next').disabled=true;$('#native-previous').disabled=true;text($('#query-http'),'Awaiting query');text($('#native-page'),'');clear($('#native-result'));text($('#native-json'),'');}
async function queryNative(params,append=false){if(!model.build)throw new Error('Select a native edition.');if(!params||typeof params!=='object'||Array.isArray(params)||Object.values(params).some(v=>typeof v!=='string'))throw new Error('Native query parameters must be a JSON object of strings.');const bid=model.build.id;const result=await api('/api/builds/'+bid+'/query?'+new URLSearchParams(params));if(model.build?.id!==bid)return result;if(!append){model.nativePages=[];model.nativeIndex=0;}else model.nativePages=model.nativePages.slice(0,model.nativeIndex+1);model.nativePages.push({params:copy(params),result});model.nativeIndex=model.nativePages.length-1;renderNative();return result;}
function renderNative(){const entry=model.nativePages[model.nativeIndex];if(!entry)return;const r=entry.result,response=r.response;$('#query-http').className='tag '+(response.status===200?'success':'error');text($('#query-http'),'Native HTTP '+response.status);text($('#native-json'),pretty(r));const body=response.body||{};renderTable($('#native-result'),body.fields||[],body.rows||[]);text($('#native-page'),'Page '+(model.nativeIndex+1)+' · '+n(body.rows?.length||0)+' returned rows · snapshot '+short(body.page?.snapshot||r.dataset?.snapshot||model.build?.native.snapshot));$('#native-previous').disabled=model.nativeIndex===0;$('#native-next').disabled=!body.page?.nextCursor;}
async function nativeNext(){const current=model.nativePages[model.nativeIndex];const cursor=current?.result.response.body.page?.nextCursor;if(!cursor)return;return queryNative({...current.params,cursor},true);}
async function compareBuilds(){const beforeId=$('#compare-before').value,afterId=$('#compare-after').value;if(!beforeId||!afterId)throw new Error('Choose both editions.');const before=model.state.builds.find(x=>x.id===beforeId),after=model.state.builds.find(x=>x.id===afterId);if(!before?.keys?.length||before.plan!==after?.plan)throw new Error('Comparison requires explicit unique keys and the same reviewed mapping.');const {result}=await mutation('comparison','/api/comparisons',{beforeId,afterId});model.comparison=result;model.changeStack=[];const box=$('#comparison-summary');box.hidden=false;text(box,pretty(result));$('#changes-download').disabled=false;await loadChanges(0);return result;}
async function loadChanges(offset){const result=await api('/api/comparisons/'+model.comparison.id+'/changes?offset='+offset+'&limit=100');model.changePage=result;const fields=Array.from(new Set(result.rows.flatMap(row=>Object.keys(row))));renderTable($('#comparison-rows'),fields,result.rows);$('#changes-next').disabled=result.nextOffset==null;$('#changes-previous').disabled=model.changeStack.length===0;}
